package com.nexustools.genericui.resources

import com.nexustools.genericui.image.ImageBuffer
import com.nexustools.genericui.image.ImageDecodeOptions
import com.nexustools.genericui.io.ByteBuffer
import com.nexustools.genericui.io.Readable
import com.nexustools.genericui.res.DrawableResource
import com.nexustools.genericui.style.color.RgbaColor
import com.nexustools.genericui.style.css.PrecompiledStyleSheet

/**
 * Typed Android-like resource handle (`R.drawable.ic_brush`, `R.string.app_name`, `RC.drawable.ic_move`, etc.)
 * generated by the GenericUI Gradle plugin (`compileGenericUiResources`) and resolved at runtime via [ResourceResolver].
 *
 * - [id]: Partitioned numeric resource ID (`0x7eTTNNNN` for `:common`, `0x60..0x7d` module byte for
 *   extensions, `0x7fTTNNNN` for consumer applications).
 * - [type]: The [ResourceType] category (`DRAWABLE`, `STRING`, `COLOR`, `DIMEN`, `RAW`, `FONT`, etc.).
 * - [name]: Snake-case resource identifier (e.g. `"ic_tool_brush"`, `"app_title"`).
 * - [relativePath]: Canonical resource relative path (`"gui/..."`, `"gui/ext/<extcat>/<ext>/..."`, or `"app/..."`).
 * - [nativeLibraryGroupId]: Native shared library group ID owning this resource (`"genericui"` for `:common`,
 *   `"genericui-ext-<ext>"` for extensions, or `""` for consumer applications).
 */
data class ResourceID(
    val id: Int,
    val type: ResourceType,
    val name: String,
    val relativePath: String = "",
    val nativeLibraryGroupId: String = defaultNativeLibraryGroupId(id)
) {
    /**
     * Module scope byte encoded in the top 8 bits of [id].
     */
    val moduleByte: Int
        get() = (id ushr 24) and 0xFF

    /**
     * Normalized canonical path without leading slash or scheme
     * (e.g. `"gui/drawable/loading.svg"`, `"gui/ext/ui/overlay/drawable/ic_play.svg"`, `"app/drawable/ic_cast.svg"`).
     */
    val canonicalRelativePath: String
        get() {
            val clean = relativePath.trim().replace('\\', '/').trimStart('/')
            if (clean.startsWith("gui/") || clean.startsWith("app/")) {
                return clean
            }
            val scopePrefix = scopePrefixFromModuleByte(moduleByte)
            if (clean.isNotEmpty()) {
                return "$scopePrefix/$clean"
            }
            return "$scopePrefix/${type.directoryName}/$name"
        }

    /**
     * Canonical path stem without the leaf file extension.
     */
    val canonicalStem: String
        get() {
            val path = canonicalRelativePath
            val lastSlash = path.lastIndexOf('/')
            val lastDot = path.lastIndexOf('.')
            return if (lastDot > lastSlash) path.substring(0, lastDot) else path
        }

    /**
     * Flat backend identifier matching Android `aapt2` (`^[a-z][a-z0-9_]*$`) and Apple `Assets.xcassets`
     * (`"gui_drawable_loading"`, `"gui_raw_bootstrap_bundle_min"`, `"gui_ext_ui_overlay_drawable_ic_play"`,
     * `"app_drawable_ic_cast"`).
     */
    val flatName: String
        get() = sanitizeFlatIdentifier(canonicalStem)

    /**
     * Prefix-free module-local native resource lookup key preserving the file extension
     * (`"drawable_loading_svg"`, `"raw_bootstrap_bundle_min_js"`, `"styles_bootstrap_scss"`,
     * `"drawable_ic_cast_svg"`).
     */
    val nativeResourceKey: String
        get() {
            val clean = relativePath.trim().replace('\\', '/').trimStart('/')
            val moduleLocal = if (clean.isNotEmpty()) {
                stripScopePrefix(clean)
            } else {
                "${type.directoryName}/$name"
            }
            return sanitizeFlatIdentifier(moduleLocal)
        }

    /**
     * C lookup function symbol name exported by the owning native shared library or host executable
     * (e.g. `"genericui_res_lookup_genericui"`, `"genericui_res_lookup_genericui_ext_alien"`,
     * `"genericui_res_lookup_app"`).
     */
    val nativeGroupLookupSymbol: String
        get() = lookupSymbolForGroup(nativeLibraryGroupId)

    /**
     * Scoped canonical URI (`"res://gui/drawable/loading"`, `"res://gui/ext/ui/overlay/drawable/ic_play"`,
     * `"res://app/drawable/ic_cast"`) understood by all GenericUI native backends.
     */
    fun toResourceUri(): String = "res://$canonicalStem"

    /**
     * Legacy unscoped URI (`"res://drawable/loading"`) retained only for explicit fallback matching.
     */
    val legacyResourceUri: String
        get() = "res://${type.directoryName}/$name"

    /**
     * Partitioned Win32 `.rc` integer resource ID in `[2000..65535]`, disjoint across module bytes
     * and never colliding with `1` (`IDI_APPICON`).
     */
    val win32ResourceId: Int
        get() {
            val slot = when (val mb = moduleByte) {
                ResourceType.CORE_MODULE_BYTE -> 0
                ResourceType.DEFAULT_APP_MODULE_BYTE -> 1
                in ResourceType.MIN_EXTENSION_MODULE_BYTE..ResourceType.MAX_EXTENSION_MODULE_BYTE ->
                    2 + (mb - ResourceType.MIN_EXTENSION_MODULE_BYTE)
                else -> 1
            }
            return 2000 + (slot * 1600) + ((type.typeCode and 0x0F) * 100) + ((id and 0xFFFF) % 100)
        }

    /** Resolves this [ResourceID] as a localized/formatted string via [ResourceResolver.getString]. */
    fun getString(vararg formatArgs: Any): String =
        ResourceResolver.getString(this, *formatArgs)

    /** Resolves this [ResourceID] as an [RgbaColor] via [ResourceResolver.getColor]. */
    fun getColor(): RgbaColor =
        ResourceResolver.getColor(this)

    /** Resolves this [ResourceID] as a pixel dimension (`Float`) via [ResourceResolver.getDimenPx]. */
    fun getDimenPx(): Float =
        ResourceResolver.getDimenPx(this)

    /** Resolves this [ResourceID] as an integer resource via [ResourceResolver.getInteger]. */
    fun getInteger(): Int =
        ResourceResolver.getInteger(this)

    /** Resolves this [ResourceID] as a boolean resource via [ResourceResolver.getBool]. */
    fun getBool(): Boolean =
        ResourceResolver.getBool(this)

    /** Resolves this [ResourceID] to a backend-appropriate URL or resource URI via [ResourceResolver.getUrl]. */
    fun getUrl(): String =
        ResourceResolver.getUrl(this)

    /** Resolves this [ResourceID] to raw binary bytes via [ResourceResolver.getBytes]. */
    fun getBytes(): ByteArray? =
        ResourceResolver.getBytes(this)

    /** Resolves this [ResourceID] to a [ByteBuffer] via [ResourceResolver.getBuffer]. */
    fun getBuffer(): ByteBuffer? =
        ResourceResolver.getBuffer(this)

    /** Asynchronously opens a non-blocking [Readable] stream for this [ResourceID] via [ResourceResolver.openReadable]. */
    suspend fun openReadable(): Readable? =
        ResourceResolver.openReadable(this)

    /** Asynchronously opens a non-blocking [Readable] stream for this [ResourceID] via [ResourceResolver.openReadable]. */
    suspend fun openStream(): Readable? =
        ResourceResolver.openReadable(this)

    /** Decodes this [ResourceID] into an [ImageBuffer] via [ResourceResolver.getImageBuffer]. */
    fun getImageBuffer(options: ImageDecodeOptions = ImageDecodeOptions()): ImageBuffer? =
        ResourceResolver.getImageBuffer(this, options)

    /** Resolves this [ResourceID] as a [DrawableResource] via [ResourceResolver.getDrawable]. */
    fun getDrawable(): DrawableResource? =
        ResourceResolver.getDrawable(this)

    /** Resolves this [ResourceID] as a [PrecompiledStyleSheet] via [ResourceResolver.getStyleSheet]. */
    fun getStyleSheet(): PrecompiledStyleSheet? =
        ResourceResolver.getStyleSheet(this)

    override fun toString(): String = toResourceUri()

    companion object {
        fun defaultNativeLibraryGroupId(id: Int): String = when ((id ushr 24) and 0xFF) {
            ResourceType.CORE_MODULE_BYTE -> "genericui"
            else -> ""
        }

        fun lookupSymbolForGroup(groupId: String): String {
            val trimmed = groupId.trim()
            if (trimmed.isEmpty() || trimmed.equals("app", ignoreCase = true)) {
                return "genericui_res_lookup_app"
            }
            return "genericui_res_lookup_${sanitizeFlatIdentifier(trimmed)}"
        }

        fun stripScopePrefix(path: String): String {
            val clean = path.trim().replace('\\', '/').trimStart('/')
            if (clean.startsWith("gui/ext/")) {
                val rest = clean.removePrefix("gui/ext/")
                val firstSlash = rest.indexOf('/')
                if (firstSlash >= 0) {
                    val secondSlash = rest.indexOf('/', firstSlash + 1)
                    if (secondSlash >= 0 && secondSlash + 1 < rest.length) {
                        return rest.substring(secondSlash + 1)
                    }
                    if (firstSlash + 1 < rest.length) {
                        return rest.substring(firstSlash + 1)
                    }
                }
                return rest
            }
            if (clean.startsWith("gui/")) {
                return clean.removePrefix("gui/")
            }
            if (clean.startsWith("app/")) {
                return clean.removePrefix("app/")
            }
            return clean
        }

        fun scopePrefixFromModuleByte(moduleByte: Int): String = when (moduleByte) {
            ResourceType.CORE_MODULE_BYTE -> "gui"
            in ResourceType.MIN_EXTENSION_MODULE_BYTE..ResourceType.MAX_EXTENSION_MODULE_BYTE -> "gui/ext"
            else -> "app"
        }

        fun sanitizeFlatIdentifier(raw: String): String {
            val trimmed = raw.trim().replace('\\', '/').trim('/')
            if (trimmed.isEmpty()) return "res_unnamed"
            val sb = StringBuilder(trimmed.length + 4)
            for (ch in trimmed) {
                val lower = ch.lowercaseChar()
                if (lower in 'a'..'z' || lower in '0'..'9' || lower == '_') {
                    sb.append(lower)
                } else {
                    sb.append('_')
                }
            }
            var out = sb.toString().trim('_')
            if (out.isEmpty()) return "res_unnamed"
            if (out[0] !in 'a'..'z') {
                out = "r_$out"
            }
            return out
        }
    }
}
